changeSet.sql:
CREATE FUNCTION prevent_archive_snapshot_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF OLD.archive_snapshot THEN
        RAISE EXCEPTION 'Archive snapshots are immutable' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER immutable_archive_snapshot BEFORE UPDATE OR DELETE ON asiakirja
    FOR EACH ROW EXECUTE FUNCTION prevent_archive_snapshot_change();

CREATE FUNCTION prevent_archive_snapshot_data_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM asiakirja WHERE asiakirja_data_id = OLD.id AND archive_snapshot) THEN
        RAISE EXCEPTION 'Archive snapshot contents are immutable' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER immutable_archive_snapshot_data BEFORE UPDATE OR DELETE ON asiakirja_data
    FOR EACH ROW EXECUTE FUNCTION prevent_archive_snapshot_data_change();

rollback.sql:
DROP TRIGGER immutable_archive_snapshot_data ON asiakirja_data;
                DROP FUNCTION prevent_archive_snapshot_data_change();
                DROP TRIGGER immutable_archive_snapshot ON asiakirja;
                DROP FUNCTION prevent_archive_snapshot_change();
